export type ParsedAwardInstruction<
  TProgram extends string = typeof BOTHEIST_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    /** The campaign's verifier signs and pays for the Claim account. */
    verifier: TAccountMetas[0];
    campaign: TAccountMetas[1];
    vault: TAccountMetas[2];
    /** `init` fails if a Claim for this (campaign, rule) already exists. */
    claim: TAccountMetas[3];
    /** The wallet bound to the winning run. Recorded in the Claim. */
    winner: TAccountMetas[4];
    systemProgram: TAccountMetas[5];
  };
  data: AwardInstructionData;
};

export function parseAwardInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedAwardInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 6) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 6,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      verifier: getNextAccount(),
      campaign: getNextAccount(),
      vault: getNextAccount(),
      claim: getNextAccount(),
      winner: getNextAccount(),
      systemProgram: getNextAccount(),
    },
    data: getAwardInstructionDataDecoder().decode(instruction.data),
  };
}
